 const [authLoading,setAuthLoading]=useState(true); const [authUser,setAuthUser]=useState(null); const [authMode,setAuthMode]=useState('login'); const [authError,setAuthError]=useState(''); const [authBusy,setAuthBusy]=useState(false); const [active,setActive]=useState('Overview'); const [mobileOpen,setMobileOpen]=useState(false); const [query,setQuery]=useState(''); const [file,setFile]=useState(null); const [rows,setRows]=useState([]); const [headers,setHeaders]=useState([]); const [target,setTarget]=useState('Class'); const [model,setModel]=useState('Logistic Regression'); const [fittedModel,setFittedModel]=useState(null); const [signInPassword,setSignInPassword]=useState(''); const [smote,setSmote]=useState(true); const [split,setSplit]=useState('80 / 20'); const [training,setTraining]=useState(false); const [trained,setTrained]=useState(false); const [trainedMetrics,setTrainedMetrics]=useState(null); const [predAmount,setPredAmount]=useState('428.50'); const [predType,setPredType]=useState('Online'); const [prediction,setPrediction]=useState(null); const [toast,setToast]=useState(''); const [theme,setTheme]=useState('light'); const [notificationsOpen,setNotificationsOpen]=useState(false); const [profileOpen,setProfileOpen]=useState(false); const [signedOut,setSignedOut]=useState(true); const [signInMode,setSignInMode]=useState(true); const [signInEmail,setSignInEmail]=useState(''); const [accountEmail,setAccountEmail]=useState('yashu.analyst@fraudshield.app'); const [accountName,setAccountName]=useState('Yashu'); const [editingProfile,setEditingProfile]=useState(false); const [editName,setEditName]=useState('Yashu'); const [editEmail,setEditEmail]=useState('yashu.analyst@fraudshield.app'); const [readNotifications,setReadNotifications]=useState([]); const fileRef=useRef(null);
 const notifications=[{id:1,icon:ShieldAlert,title:'Suspicious transaction flagged for review.',time:'2 minutes ago',tone:'red'},{id:2,icon:CheckCircle2,title:'Fraud detection model is ready to review.',time:'Today, 10:42 AM',tone:'green'},{id:3,icon:Database,title:'Sample transaction dataset loaded successfully.',time:'Today, 9:30 AM',tone:'blue'},{id:4,icon:Activity,title:'Weekly fraud monitoring summary is available.',time:'Yesterday',tone:'purple'},{id:5,icon:ShieldCheck,title:'Your workspace security check is complete.',time:'Monday',tone:'green'}];
