 useEffect(()=>{let live=true;api('/auth/me').then(data=>{if(!live)return;setAuthUser(data.user);setAccountName(data.user.name);setAccountEmail(data.user.email);setEditName(data.user.name);setEditEmail(data.user.email);setSignedOut(false);}).catch(()=>{if(live){setAuthUser(null);setSignedOut(true);}}).finally(()=>{if(live)setAuthLoading(false)});return()=>{live=false}},[]);
 const submitAuth=async(e)=>{e.preventDefault();setAuthError('');setAuthBusy(true);try{const path=authMode==='register'?'/auth/register':'/auth/login';const data=await api(path,{method:'POST',body:JSON.stringify({name:signInName,email:signInEmail,password:signInPassword})});setAuthUser(data.user);setAccountName(data.user.name);setAccountEmail(data.user.email);setEditName(data.user.name);setEditEmail(data.user.email);setSignedOut(false);setSignInPassword('');showToast(authMode==='register'?'Account created successfully.':'Signed in successfully.');}catch(err){setAuthError(err.message)}finally{setAuthBusy(false)}};
