 const filteredRows=useMemo(()=>{const source=rows.length?rows.map((r,i)=>{const vals=Object.values(r);const amountKey=headers.find(h=>/amount|value|transaction_amt/i.test(h));const channelKey=headers.find(h=>/channel|type|method/i.test(h));const label=String(r[target]??'Unknown');const fraud=['1','fraud','true','yes'].includes(label.trim().toLowerCase());return {id:String(r.transaction_id||r.TransactionID||r.id||`CSV-${String(i+1).padStart(5,'0')}`),amount:amountKey?String(r[amountKey]):'—',time:'Uploaded dataset',method:channelKey?String(r[channelKey]):'Unknown',status:fraud?'Fraud':label,score:'—'};}):sampleRows;return source.filter(r=>(r.id+' '+r.amount+' '+r.method+' '+r.status).toLowerCase().includes(query.toLowerCase()));},[query,rows,headers,target]);
 const onFile=(f)=>{if(!f)return; if(!f.name.toLowerCase().endsWith('.csv')){showToast('Please upload a CSV file.');return;} setFile(f); Papa.parse(f,{header:true,skipEmptyLines:true,dynamicTyping:false,complete:(res)=>{setHeaders(res.meta.fields||[]);setRows(res.data||[]);setTrained(false);setTrainedMetrics(null);setFittedModel(null);setPrediction(null);showToast(`Loaded ${res.data.length.toLocaleString()} rows from ${f.name}`);},error:()=>showToast('Could not read this CSV file.')});};
 const runTraining=()=>{
  if(!rows.length){showToast('Upload a labelled CSV dataset first to train on your own data.');setActive('Dataset Explorer');return;}
  if(!headers.includes(target)){showToast('Choose a target column that exists in your dataset.');return;}
  const labelOf=v=>{const x=String(v??'').trim().toLowerCase();if(['1','fraud','true','yes'].includes(x))return 1;if(['0','legitimate','normal','false','no','genuine'].includes(x))return 0;return null;};
  const labelled=rows.map(r=>({row:r,y:labelOf(r[target])})).filter(x=>x.y!==null);
  const featureCols=headers.filter(h=>h!==target && rows.some(r=>String(r[h]??'').trim()!=='' && Number.isFinite(Number(r[h]))));
  if(labelled.length<10||new Set(labelled.map(x=>x.y)).size<2){showToast('Training needs at least 10 labelled rows and both legitimate (0) and fraud (1) classes.');return;}
  if(!featureCols.length){showToast('No numeric feature columns found. Include numeric transaction features in your CSV.');return;}
  const data=labelled.map(x=>({y:x.y,values:featureCols.map(h=>{const v=Number(x.row[h]);return Number.isFinite(v)?v:0;})}));
  const means=featureCols.map((_,j)=>data.reduce((a,d)=>a+d.values[j],0)/data.length);
  const scales=featureCols.map((_,j)=>Math.sqrt(data.reduce((a,d)=>a+(d.values[j]-means[j])**2,0)/data.length)||1);
  const normalized=data.map(d=>({y:d.y,x:d.values.map((v,j)=>(v-means[j])/scales[j])}));
  // Shuffle before splitting; fit a real binary logistic-regression model using gradient descent.
  for(let i=normalized.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[normalized[i],normalized[j]]=[normalized[j],normalized[i]];}
  const trainN=Math.max(5,Math.min(normalized.length-2,Math.floor(normalized.length*Number(split.split('/')[0].trim())/100)));
  const train=normalized.slice(0,trainN), test=normalized.slice(trainN); let weights=Array(featureCols.length).fill(0), bias=0; const rate=.08, epochs=700;
  const sigmoid=z=>1/(1+Math.exp(-Math.max(-30,Math.min(30,z))));
  for(let epoch=0;epoch<epochs;epoch++){const gw=Array(weights.length).fill(0);let gb=0;const positives=train.filter(d=>d.y===1).length;const negatives=train.length-positives;for(const d of train){const p=sigmoid(bias+weights.reduce((a,w,j)=>a+w*d.x[j],0));const classWeight=smote&&d.y===1?Math.max(1,Math.min(10,negatives/Math.max(positives,1))):1;const e=(p-d.y)*classWeight;gb+=e;for(let j=0;j<weights.length;j++)gw[j]+=e*d.x[j];}bias-=rate*gb/train.length;for(let j=0;j<weights.length;j++)weights[j]-=rate*(gw[j]/train.length+.001*weights[j]);}
  const scored=test.map(d=>({y:d.y,p:sigmoid(bias+weights.reduce((a,w,j)=>a+w*d.x[j],0))}));const tp=scored.filter(d=>d.p>=.5&&d.y===1).length, fp=scored.filter(d=>d.p>=.5&&d.y===0).length, fn=scored.filter(d=>d.p<.5&&d.y===1).length;
  const precision=tp/(tp+fp||1), recall=tp/(tp+fn||1), f1=2*precision*recall/(precision+recall||1);
  const positives=scored.filter(d=>d.y===1), negatives=scored.filter(d=>d.y===0);let wins=0,pairs=0;for(const a of positives)for(const b of negatives){pairs++;wins+=a.p>b.p?1:a.p===b.p?.5:0;}const auc=pairs?wins/pairs:0;
  const fitted={featureCols,means,scales,weights,bias,threshold:.5,trainingRows:train.length,testRows:test.length};setFittedModel(fitted);setTrained(true);setTrainedMetrics({precision:Number((precision*100).toFixed(1)),recall:Number((recall*100).toFixed(1)),f1:Number((f1*100).toFixed(1)),auc:Number(auc.toFixed(3))});setPrediction(null);showToast(`Logistic Regression trained and evaluated on ${test.length} held-out rows.`);
 };
 const predict=()=>{const amount=Number(predAmount);if(!Number.isFinite(amount)||amount<0){showToast('Enter a valid non-negative transaction amount.');return;} if(!fittedModel){showToast('Train Logistic Regression on a labelled CSV first.');setActive('Train & Tune');return;}const sigmoid=z=>1/(1+Math.exp(-Math.max(-30,Math.min(30,z))));const x=fittedModel.featureCols.map((h,j)=>{if(/amount|amt|value|transaction_amt/i.test(h))return (amount-fittedModel.means[j])/fittedModel.scales[j];return (0-fittedModel.means[j])/fittedModel.scales[j];});const risk=sigmoid(fittedModel.bias+fittedModel.weights.reduce((a,w,j)=>a+w*x[j],0));setPrediction({risk,label:risk>=.7?'Likely fraud':risk>=.35?'Needs review':'Likely legitimate',amount:amount.toFixed(2),source:'Trained Logistic Regression'});};
 const downloadReport=()=>{const csvCell=value=>'"'+String(value??'').replaceAll('"','""')+'"';const report=[['FraudShield Model Report'],['Generated at',new Date().toISOString()],['Dataset',file?.name||'Built-in sample data'],['Dataset rows',rows.length||'Not uploaded'],['Selected classifier',model],['Training status',trainedMetrics?'Completed':'Not trained'],['Metrics status',trainedMetrics?'Calculated from held-out test rows':'Unavailable — no model has been fitted'],['Precision',trainedMetrics?.precision??'N/A'],['Recall',trainedMetrics?.recall??'N/A'],['F1-score',trainedMetrics?.f1??'N/A'],['ROC-AUC',trainedMetrics?.auc??'N/A'],['Notice','Metrics are calculated on a held-out test split from the uploaded CSV. This educational prototype is not production financial software.']].map(row=>row.map(csvCell).join(',')).join('\r\n');const blob=new Blob(['\ufeff'+report],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='fraudshield-model-report.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);showToast('Report downloaded with unavailable metrics marked N/A.');};
