 const titleMap={'Notifications':'Notifications','Profile':'My Profile','Overview':'Fraud Detection Dashboard','Dataset Explorer':'Dataset Explorer','Data Preprocessing':'Data Preprocessing','Classifier Models':'Classifier Models','Train & Tune':'Train & Tune','Model Evaluation':'Model Evaluation','Fraud Prediction':'Fraud Prediction','Reports':'Reports & Exports','Settings':'Workspace Settings'};
